/// HTML wrapper simulating the actual BoM page structure.
String wrapInHtml(String advisoryText) {
  return '''
<html>
<head><title>Volcanic ASH Advisories</title></head>
<body>
<h2>Volcanic Ash Advisories Received in Last 7 Days</h2>
<table>
<tr><td><h3>Darwin VAAC</h3><pre>IDD60020
     VOLCANIC ASH ADVISORIES FROM DARWIN VAAC - LAST 7 DAYS
                  DARWIN VAAC      16:00 UTC, 05/09/2026
--------------------------------------------------------------------

$advisoryText

</pre></td></tr>
</table>
</body>
</html>
''';
}
